files.content:
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: #f9f6f1;
  color: #3c3031;
}

.menu {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 32px;
  background: #3c3031;
}

.menu a {
  color: #ffffff;
  text-decoration: none;
}

.logo {
  font-size: 22px;
  font-weight: bold;
}

nav a {
  margin-left: 20px;
}

nav a:hover {
  color: #f2c6a5;
}

.banner {
  padding: 80px 20px;
  background: #e07b60;
  color: #ffffff;
  text-align: center;
}

.banner h1 {
  margin: 0 0 12px;
  font-size: 48px;
}

.banner p {
  margin: 0;
  font-size: 18px;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 24px;
  padding: 48px 20px;
}

.card {
  width: 260px;
  padding: 16px;
  background: #ffffff;
  border: 1px solid #dad5ce;
  border-radius: 12px;
  cursor: pointer;
}

.card.picked {
  border: 3px solid #e07b60;
}

.picture {
  height: 140px;
  border-radius: 8px;
  background: #f2c6a5;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 56px;
}

.card h2 {
  margin: 16px 0 8px;
  font-size: 20px;
}

.card p {
  margin: 0;
  color: #8a817c;
}

.footer {
  padding: 20px;
  background: #3c3031;
  color: #ffffff;
  text-align: center;
}

const cards = document.querySelectorAll(".card");

cards.forEach(function (card) {
  card.addEventListener("click", function () {
    cards.forEach(function (other) {
      other.classList.remove("picked");
    });
    card.classList.add("picked");
  });
});

